// --- Image Upload ---

app.post('/api/upload', requireAuth, upload.single('file'), (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  const host = req.headers['x-forwarded-host'] || req.headers.host;
  const proto = req.headers['x-forwarded-proto'] || req.protocol;

  const slot = (req.body.slot || '').replace(/[^a-z0-9\-_]/gi, ''); // sanitize
  if (slot) {
    const ext = path.extname(req.file.originalname).toLowerCase() || '.jpg';
    const stableName = slot + ext;
    const stablePath = path.join(uploadsDir, stableName);
    // Delete any existing file with the same slot (handles extension changes)
    try {
      fs.readdirSync(uploadsDir)
        .filter(f => f.startsWith(slot + '.'))
        .forEach(f => fs.unlinkSync(path.join(uploadsDir, f)));
    } catch {}
    fs.renameSync(req.file.path, stablePath);
    return res.json({ url: `${proto}://${host}/uploads/${stableName}?v=${Date.now()}` });
  }

  res.json({ url: `${proto}://${host}/uploads/${req.file.filename}` });
});

// --- Settings ---

app.get('/api/settings', (req, res) => {
  const rows = db.prepare('SELECT key, value FROM settings').all();
  res.json(Object.fromEntries(rows.map(r => [r.key, r.value])));
});

app.put('/api/settings', requireAuth, (req, res) => {
  const update = db.prepare('INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)');
  const updateMany = db.transaction((data) => {
    for (const [key, value] of Object.entries(data)) update.run(key, value ?? '');
  });
  updateMany(req.body);
  res.json({ success: true });
});

