// --- Social Icon Management ---

app.get('/api/social-icons', (req, res) => {
  try {
    const files = fs.readdirSync(socialIconsDir)
      .filter(f => /\.(png|jpg|jpeg|gif|svg|webp)$/i.test(f))
      .map(f => ({ name: f.replace(/\.[^.]+$/, ''), url: `/social-icons/${f}` }));
    res.json(files);
  } catch { res.json([]); }
});

const socialIconUpload = multer({
  storage: multer.diskStorage({
    destination: (req, file, cb) => cb(null, socialIconsDir),
    filename: (req, file, cb) => {
      const name = (req.body.name || '').replace(/[^a-z0-9\-]/gi, '').toLowerCase();
      if (!name) return cb(new Error('Icon name required'));
      const ext = path.extname(file.originalname).toLowerCase() || '.png';
      cb(null, name + ext);
    }
  }),
  limits: { fileSize: 2 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype.startsWith('image/')) cb(null, true);
    else cb(new Error('Images only'));
  }
});

app.post('/api/social-icons', requireAuth, (req, res, next) => {
  socialIconUpload.single('file')(req, res, err => {
    if (err) return res.status(400).json({ error: err.message });
    if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
    res.json({ url: `/social-icons/${req.file.filename}` });
  });
});

app.delete('/api/social-icons/:name', requireAuth, (req, res) => {
  const name = req.params.name.replace(/[^a-z0-9\-]/gi, '').toLowerCase();
  const files = fs.readdirSync(socialIconsDir).filter(f => f.replace(/\.[^.]+$/, '') === name);
  files.forEach(f => { try { fs.unlinkSync(path.join(socialIconsDir, f)); } catch {} });
  res.json({ success: true });
});

