file.content:
.social-thumb-wrap svg { opacity: 0.3; }
.social-icon-row .icon-url { flex: 1.2; }
.social-icon-row .profile-url { flex: 1.4; }
.social-row-num { font-size: 11px; color: var(--text-muted); font-weight: 600; width: 16px; text-align: right; flex-shrink: 0; }

/* ── Banner ── */
.banner-section-inner { display: flex; flex-direction: column; gap: 10px; }
.banner-preview-wrap {
  background: var(--bg); border-radius: 10px; border: 1px solid var(--border);
  min-height: 60px; align-items: center; justify-content: center; overflow: hidden; display: none;
}
.banner-preview-wrap img { max-width: 100%; max-height: 100px; object-fit: contain; }
.banner-preview-wrap.has-banner { display: flex; }

/* ── Search + section header ── */

