/* ── Social Icons Library ── */
.icon-library-card {
  background: var(--surface); border-radius: 14px;
  border: 1px solid var(--border); border-top: 3px solid var(--lime);
  padding: 28px 32px; margin-bottom: 28px;
}
.icon-library-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 20px;
}
.icon-library-title { font-size: 16px; font-weight: 700; color: var(--text); }
.icon-library-sub { font-size: 13px; color: var(--text-muted); margin-top: 2px; }
.icon-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 14px; margin-bottom: 24px;
}
.icon-tile {
  background: var(--bg); border: 1px solid var(--border); border-radius: 10px;
  padding: 14px 10px 10px; display: flex; flex-direction: column;
  align-items: center; gap: 8px; text-align: center;
}
.icon-tile img { width: 40px; height: 40px; object-fit: contain; }
.icon-tile-name { font-size: 11px; font-weight: 600; color: var(--text-muted); word-break: break-all; }
.icon-tile-actions { display: flex; gap: 6px; }
.icon-tile-actions button { font-size: 11px; padding: 3px 8px; border-radius: 6px; border: 1px solid var(--border); background: var(--surface); color: var(--text); cursor: pointer; }
.icon-tile-actions button:hover { background: var(--lime); color: var(--navy); border-color: var(--lime); }
.icon-tile-actions .del-btn:hover { background: #fee2e2; color: #dc2626; border-color: #fca5a5; }
.icon-add-row { display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap; }
.icon-add-row .field-group { flex: 1; min-width: 140px; }

/* ── Search + section header ── */

