  // ── Social Icons Library ──────────────────────────────────────────────────

  async function loadSocialIcons() {
    const grid = document.getElementById('icon-grid');
    const token = sessionStorage.getItem('adminToken') || '';
    const res = await fetch('/api/social-icons', { headers: { 'x-admin-token': token } });
    const icons = await res.json();
    if (!icons.length) {
      grid.innerHTML = '<div style="color:var(--text-muted);font-size:13px;">No icons yet.</div>';
      return;
    }
    grid.innerHTML = icons.map(ic => `
      <div class="icon-tile" id="tile-${ic.name}">
        <img src="${ic.url}?v=${Date.now()}" alt="${ic.name}" />
        <div class="icon-tile-name">${ic.name}</div>
        <div style="font-size:10px;color:var(--text-muted);word-break:break-all;margin-top:-4px;">/social-icons/${ic.name}.png</div>
        <div class="icon-tile-actions">
          <button onclick="replaceIcon('${ic.name}')">Replace</button>
          <button class="del-btn" onclick="deleteIcon('${ic.name}')">Delete</button>
        </div>
      </div>`).join('');
  }

  function replaceIcon(name) {
    document.getElementById('new-icon-name').value = name;
    document.getElementById('new-icon-file').value = '';
    document.getElementById('new-icon-file').click();
    document.getElementById('new-icon-file').onchange = () => uploadSocialIcon();
  }

  async function uploadSocialIcon() {
    const name = document.getElementById('new-icon-name').value.trim().replace(/[^a-z0-9\-]/gi, '').toLowerCase();
    const file = document.getElementById('new-icon-file').files[0];
    const msg = document.getElementById('icon-upload-msg');
    if (!name) { msg.style.display = ''; msg.style.color = '#dc2626'; msg.textContent = 'Enter an icon name first.'; return; }
    if (!file) { msg.style.display = ''; msg.style.color = '#dc2626'; msg.textContent = 'Select an image file.'; return; }
    const formData = new FormData();
    formData.append('name', name);
    formData.append('file', file);
    const token = sessionStorage.getItem('adminToken') || '';
    const res = await fetch('/api/social-icons', { method: 'POST', headers: { 'x-admin-token': token }, body: formData });
    if (!res.ok) { msg.style.display = ''; msg.style.color = '#dc2626'; msg.textContent = 'Upload failed.'; return; }
    msg.style.display = '';
    msg.style.color = 'var(--text)';
    msg.textContent = `✓ Saved as /social-icons/${name}.png`;
    document.getElementById('new-icon-name').value = '';
    document.getElementById('new-icon-file').value = '';
    document.getElementById('new-icon-file').onchange = null;
    loadSocialIcons();
  }

  async function deleteIcon(name) {
    if (!confirm(`Delete the "${name}" icon? Any signatures using /social-icons/${name}.png will show a broken image.`)) return;
    const token = sessionStorage.getItem('adminToken') || '';
    await fetch(`/api/social-icons/${name}`, { method: 'DELETE', headers: { 'x-admin-token': token } });
    loadSocialIcons();
  }
</script>

