function clearBanner() { s('f-banner-url', ''); s('f-banner-link', ''); prevBanner(''); up(); }

function uploadBanner() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = async () => {
    const file = input.files[0];
    if (!file) return;
    const empId = location.pathname.split('/').pop();
    const formData = new FormData();
    formData.append('file', file);
    formData.append('slot', `banner-emp-${empId}`);
    const token = sessionStorage.getItem('adminToken') || '';
    const res = await fetch('/api/upload', { method: 'POST', headers: { 'x-admin-token': token }, body: formData });
    if (!res.ok) {
      showToast(res.status === 401 ? 'Session expired — please log out and log back in as admin.' : 'Upload failed. Please try again.');
      return;
    }
    const { url } = await res.json();
    s('f-banner-url', url);
    prevBanner(url);
    up();
  };
  input.click();
}

function uploadPhoto() {
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = async () => {
    const file = input.files[0];
    if (!file) return;
    const empId = location.pathname.split('/').pop();
    const formData = new FormData();
    formData.append('file', file);
    formData.append('slot', `photo-${empId}`);
    const token = sessionStorage.getItem('adminToken') || '';
    const res = await fetch('/api/upload', { method: 'POST', headers: { 'x-admin-token': token }, body: formData });
    if (!res.ok) {
      showToast(res.status === 401 ? 'Session expired — please log out and log back in as admin.' : 'Upload failed. Please try again.');
      return;
    }
    const { url } = await res.json();
    s('f-photo-url', url);
    prevPhoto(url);
    up();
  };
  input.click();
}

// Toggle custom profile UI
function onProfileChange() {
  const profile = g('f-company-profile');
  const isCustom = profile && profile !== '';
  gf('dr-master-note').style.display      = isCustom ? 'none' : 'block';
  gf('custom-profile-note').style.display = isCustom ? 'block' : 'none';
  gf('custom-contact-block').style.display = isCustom ? 'block' : 'none';
  gf('custom-social-block').style.display  = isCustom ? 'block' : 'none';

