  // ── Drag-and-drop uploads ──────────────────────────────────────────────────

  function makeDropZone(el, onFile) {
    el.addEventListener('dragover', e => { e.preventDefault(); el.classList.add('dz-over'); });
    el.addEventListener('dragleave', e => { if (!el.contains(e.relatedTarget)) el.classList.remove('dz-over'); });
    el.addEventListener('drop', e => {
      e.preventDefault();
      el.classList.remove('dz-over');
      const file = e.dataTransfer.files[0];
      if (file && file.type.startsWith('image/')) onFile(file);
    });
  }

  async function doEditUpload(file, slot, fieldId, previewFn) {
    const empId = location.pathname.split('/').pop();
    const formData = new FormData();
    formData.append('file', file);
    formData.append('slot', `${slot}-${empId}`);
    const token = sessionStorage.getItem('adminToken') || '';
    const res = await fetch('/api/upload', { method: 'POST', headers: { 'x-admin-token': token }, body: formData });
    if (!res.ok) {
      showToast(res.status === 401 ? 'Session expired — please log out and log back in as admin.' : 'Upload failed. Please try again.');
      return;
    }
    const { url } = await res.json();
    s(fieldId, url);
    previewFn(url);
    up();
  }

  makeDropZone(document.getElementById('photo-wrap'),  file => doEditUpload(file, 'photo',      'f-photo-url',  prevPhoto));
  makeDropZone(document.getElementById('banner-wrap'), file => doEditUpload(file, 'banner-emp', 'f-banner-url', prevBanner));
</script>

