// ── Drag-and-drop uploads ──────────────────────────────────────────────────

function makeDropZone(el, onFile) {
  if (!el) return;
  el.addEventListener('dragover', e => { e.preventDefault(); el.classList.add('dz-over'); });
  el.addEventListener('dragleave', e => { if (!el.contains(e.relatedTarget)) el.classList.remove('dz-over'); });
  el.addEventListener('drop', e => {
    e.preventDefault();
    el.classList.remove('dz-over');
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('image/')) onFile(file);
  });
}

async function doMasterUpload(file, fieldId, previewFn, slot) {
  const formData = new FormData();
  formData.append('file', file);
  if (slot) formData.append('slot', slot);
  try {
    const res = await adminFetch('/api/upload', { method: 'POST', body: formData });
    if (!res.ok) throw new Error();
    const { url } = await res.json();
    const field = document.getElementById(fieldId);
    if (field) field.value = url;
    if (previewFn) previewFn(url);
  } catch {
    showToast('Upload failed. Please try again.');
  }
}

async function doSocialIconDrop(file) {
  const name = (document.getElementById('new-icon-name').value || '').trim().replace(/[^a-z0-9\-]/gi, '').toLowerCase();
  const msg = document.getElementById('icon-upload-msg');
  if (!name) {
    msg.style.display = ''; msg.style.color = '#dc2626';
    msg.textContent = 'Enter an icon name above first, then drop the image.';
    return;
  }
  const formData = new FormData();
  formData.append('name', name);
  formData.append('file', file);
  const token = sessionStorage.getItem('adminToken') || '';
  const res = await fetch('/api/social-icons', { method: 'POST', headers: { 'x-admin-token': token }, body: formData });
  if (!res.ok) { msg.style.display = ''; msg.style.color = '#dc2626'; msg.textContent = 'Upload failed.'; return; }
  msg.style.display = ''; msg.style.color = 'var(--text)';
  msg.textContent = `✓ Saved as /social-icons/${name}.png`;
  document.getElementById('new-icon-name').value = '';
  loadSocialIcons();
}

if (!viewerToken && !adminToken) {
  window.location.href = '/login';
} else {
  buildSocialRows();
  // Wire drop zones on social icon thumbnails (built in buildSocialRows)
  for (let i = 1; i <= 10; i++) {
    makeDropZone(document.getElementById(`s-social-thumb-wrap-${i}`),
      file => doMasterUpload(file, `s-social-icon-${i}`, v => updateSocialThumb(i, v), `social-${i}`));
  }
  // Wire drop zones on logo and banner (static elements)
  makeDropZone(document.querySelector('.logo-row'),
    file => doMasterUpload(file, 's-logo', previewLogo, 'logo-master'));
  makeDropZone(document.getElementById('banner-preview-wrap'),
    file => doMasterUpload(file, 's-banner-url', previewBanner, 'banner-master'));
  checkAuth().then(() => { if (isAdmin) loadSettings(); });
  loadEmployees();
}

// ── Social Icons Library ──────────────────────────────────────────────────

