app.post('/api/viewer-login', (req, res) => {
  const { password } = req.body;
  const row = db.prepare("SELECT value FROM settings WHERE key = 'viewer_password'").get();
  const stored = row?.value || '';
  if (!stored || password !== stored) return res.status(401).json({ error: 'Wrong password' });
  const token = uuidv4();
  viewerSessions.add(token);
  res.json({ token });
});

