    .header-right { display: flex; align-items: center; gap: 12px; }

    .btn { padding: 8px 18px; border: none; border-radius: 6px; cursor: pointer; font-size: 14px; font-weight: 500; transition: all 0.15s; }
    .btn-primary { background: #0066CC; color: white; }
    .btn-primary:hover { background: #0055aa; }
    .btn-danger { background: #e53e3e; color: white; }
    .btn-danger:hover { background: #c53030; }
    .btn-ghost { background: transparent; color: white; border: 1px solid rgba(255,255,255,0.3); }
    .btn-ghost:hover { background: rgba(255,255,255,0.1); }
    .btn-sm { padding: 5px 14px; font-size: 13px; }
    .btn-master-save { background: #F6921C; color: white; border: none; border-radius: 6px; padding: 9px 22px; font-size: 14px; font-weight: 600; cursor: pointer; transition: background 0.15s; white-space: nowrap; }
    .btn-master-save:hover { background: #e07d10; }
    .btn-master-save.saved { background: #0A8A4A; }

    .container { max-width: 1100px; margin: 0 auto; padding: 32px 24px; }

    /* Master Template Card */
    .master-card { background: white; border-radius: 12px; box-shadow: 0 4px 24px rgba(0,0,0,0.13); margin-bottom: 32px; overflow: hidden; }
    .master-header { background: #1a1a2e; padding: 18px 28px; display: flex; align-items: center; gap: 20px; }
    .master-header-icon { width: 42px; height: 42px; background: rgba(246,146,28,0.2); border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .master-header-icon svg { width: 22px; height: 22px; }
    .master-header-text { flex: 1; }
    .master-header-title { font-size: 16px; font-weight: 700; color: white; letter-spacing: 0.3px; }
    .master-header-sub { font-size: 12px; color: rgba(255,255,255,0.5); margin-top: 2px; }
    .master-body { padding: 0; }
    .master-section { padding: 22px 28px; border-bottom: 1px solid #f0f2f5; }
    .master-section:last-child { border-bottom: none; }
    .master-section-title { font-size: 11px; font-weight: 700; color: #999; text-transform: uppercase; letter-spacing: 0.6px; margin-bottom: 14px; display: flex; align-items: center; gap: 6px; }
    .master-section-title svg { opacity: 0.6; }

    .company-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    .company-grid .full { grid-column: span 2; }
    .field-label { font-size: 11px; font-weight: 600; color: #888; text-transform: uppercase; letter-spacing: 0.4px; margin-bottom: 4px; }
    .field-group { display: flex; flex-direction: column; }
    .input-with-label { display: flex; gap: 6px; }
    .input-with-label .label-input { width: 54px; flex-shrink: 0; }
    .input-with-label .value-input { flex: 1; }

    input[type="text"], input[type="email"], input[type="url"] {
      padding: 8px 10px; border: 1px solid #dde1e7; border-radius: 6px; font-size: 13px;
      color: #333; outline: none; transition: border-color 0.15s, box-shadow 0.15s; background: white; width: 100%;
    }
    input:focus { border-color: #0066CC; box-shadow: 0 0 0 3px rgba(0,102,204,0.1); }
    input::placeholder { color: #bbb; }

    .logo-row { display: flex; align-items: center; gap: 10px; }
    .logo-preview { height: 34px; width: auto; border-radius: 4px; border: 1px solid #eee; display: none; max-width: 100px; }

    /* Social rows */
    .social-rows-list { display: flex; flex-direction: column; gap: 8px; }
    .social-icon-row { display: flex; align-items: center; gap: 10px; }
    .social-thumb-wrap { width: 34px; height: 34px; border-radius: 6px; background: #f0f2f5; border: 1px solid #e0e4ea; flex-shrink: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; }
    .social-thumb-wrap img { width: 100%; height: 100%; object-fit: contain; display: none; }
    .social-thumb-wrap svg { opacity: 0.3; }
    .social-icon-row .icon-url { flex: 1.2; }
    .social-icon-row .profile-url { flex: 1.4; }
    .social-row-num { font-size: 11px; color: #ccc; font-weight: 600; width: 16px; text-align: right; flex-shrink: 0; }

    /* Banner */
    .banner-section-inner { display: flex; flex-direction: column; gap: 10px; }
    .banner-preview-wrap { background: #f7f8fa; border-radius: 8px; border: 1px solid #eee; min-height: 60px; display: flex; align-items: center; justify-content: center; overflow: hidden; display: none; }
    .banner-preview-wrap img { max-width: 100%; max-height: 100px; object-fit: contain; }
    .banner-preview-wrap.has-banner { display: flex; }

    /* Toolbar + table (same as before) */
    .toolbar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 24px; gap: 12px; flex-wrap: wrap; }
    .search-box { flex: 1; max-width: 360px; padding: 9px 14px; border: 1px solid #dde1e7; border-radius: 6px; font-size: 14px; background: white; outline: none; }
    .search-box:focus { border-color: #0066CC; box-shadow: 0 0 0 3px rgba(0,102,204,0.1); }
    .section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
    .section-header h2 { font-size: 16px; font-weight: 700; color: #1a1a2e; }
    .stats { font-size: 13px; color: #666; }

    .table-wrap { background: white; border-radius: 10px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); overflow: hidden; }
    table { width: 100%; border-collapse: collapse; }
    thead { background: #f7f8fa; }
    th { padding: 12px 16px; text-align: left; font-size: 12px; font-weight: 600; color: #888; text-transform: uppercase; letter-spacing: 0.5px; border-bottom: 1px solid #eee; }
    td { padding: 14px 16px; font-size: 14px; border-bottom: 1px solid #f0f0f0; vertical-align: middle; }
    tr:last-child td { border-bottom: none; }
    tr:hover td { background: #fafbff; }

    .avatar { width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 600; font-size: 14px; color: white; flex-shrink: 0; }
    .name-cell { display: flex; align-items: center; gap: 10px; }
    .name-text { font-weight: 500; }
    .sub-text { font-size: 12px; color: #888; margin-top: 1px; }
    .badge { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 500; background: #e8f0fe; color: #0066CC; }
    .actions { display: flex; gap: 6px; }
    .copy-link { background: #f0f2f5; border: none; border-radius: 5px; padding: 5px 10px; font-size: 12px; cursor: pointer; color: #444; transition: all 0.15s; display: flex; align-items: center; gap: 4px; }
    .copy-link:hover { background: #e0e4ea; }
    .copy-link.copied { background: #d4edda; color: #1a7a3a; }

    .empty { text-align: center; padding: 80px 20px; color: #aaa; }
    .empty h3 { font-size: 18px; margin-bottom: 8px; color: #888; }

    /* Modal */
    .modal-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 100; align-items: center; justify-content: center; }
    .modal-overlay.open { display: flex; }
    .modal { background: white; border-radius: 12px; width: 100%; max-width: 420px; padding: 32px; box-shadow: 0 20px 60px rgba(0,0,0,0.2); }
    .modal h2 { font-size: 20px; margin-bottom: 24px; }
    .form-group { display: flex; flex-direction: column; gap: 5px; margin-bottom: 14px; }
    .form-group:last-of-type { margin-bottom: 0; }
    .form-group label { font-size: 12px; font-weight: 600; color: #555; text-transform: uppercase; letter-spacing: 0.4px; }
    .modal-footer { display: flex; justify-content: flex-end; gap: 10px; margin-top: 28px; padding-top: 20px; border-top: 1px solid #eee; }
    .btn-cancel { background: #f0f2f5; color: #333; }
    .btn-cancel:hover { background: #e0e4ea; }

    .toast { position: fixed; bottom: 24px; right: 24px; background: #1a1a2e; color: white; padding: 12px 20px; border-radius: 8px; font-size: 14px; opacity: 0; transition: opacity 0.3s; z-index: 200; pointer-events: none; }
    .toast.show { opacity: 1; }

    @media (max-width: 700px) {
      .company-grid { grid-template-columns: 1fr; }
      .company-grid .full { grid-column: span 1; }
    }
  </style>
</head>
<body>

<header>
  <h1>&#9993; Email Signature Manager</h1>
  <div class="header-right">
    <span id="header-count" class="stats" style="color:rgba(255,255,255,0.6)"></span>
    <button class="btn btn-ghost admin-only" id="add-emp-header-btn" onclick="openModal()" style="display:none">+ Add Employee</button>
    <button class="btn btn-ghost" id="auth-btn" onclick="handleAuthBtn()">&#128274; Admin Login</button>
  </div>
</header>

<div class="container">

  <!-- MASTER TEMPLATE CARD (admin only) -->
  <div class="master-card admin-only" id="master-card" style="display:none">
    <div class="master-header">
      <div class="master-header-icon">
        <svg viewBox="0 0 24 24" fill="none" stroke="#F6921C" stroke-width="2"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
      </div>
      <div class="master-header-text">
        <div class="master-header-title">Master Signature Template</div>
        <div class="master-header-sub">Company-wide settings applied to all employee signatures automatically</div>
      </div>
      <button class="btn-master-save" id="master-save-btn" onclick="saveMaster()">Save Master Template</button>
    </div>

    <div class="master-body">

      <!-- Company Info -->
      <div class="master-section">
        <div class="master-section-title">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9,22 9,12 15,12 15,22"/></svg>
          Company Info
        </div>
        <div class="company-grid">
          <div class="field-group">
            <div class="field-label">Company Name</div>
            <input type="text" id="s-company" placeholder="Acme Corporation" />
          </div>
          <div class="field-group">
            <div class="field-label">Logo URL</div>
            <div class="logo-row">
              <input type="text" id="s-logo" placeholder="https://company.com/logo.png" oninput="previewLogo(this.value)" style="flex:1;" />
              <img id="logo-preview" class="logo-preview" alt="Logo" />
            </div>
          </div>
          <div class="field-group">
            <div class="field-label">Phone Label &amp; Number</div>
            <div class="input-with-label">
              <input type="text" class="label-input" id="s-phone-label" placeholder="p:" />
              <input type="text" class="value-input" id="s-phone" placeholder="(561) 555-0100" />
            </div>
          </div>
          <div class="field-group">
            <div class="field-label">Website Label &amp; URL</div>
            <div class="input-with-label">
              <input type="text" class="label-input" id="s-website-label" placeholder="w:" />
              <input type="text" class="value-input" id="s-website" placeholder="www.company.com" />
            </div>
          </div>
          <div class="field-group">
            <div class="field-label">Address Label &amp; Line 1</div>
            <div class="input-with-label">
              <input type="text" class="label-input" id="s-address-label" placeholder="a:" />
              <input type="text" class="value-input" id="s-address" placeholder="901 Northpoint Pkwy, Suite 105" />
            </div>
          </div>
          <div class="field-group">
            <div class="field-label">Address Line 2</div>
            <input type="text" id="s-address2" placeholder="West Palm Beach, FL 33407" />
          </div>
          <div class="field-group">
            <div class="field-label">Photo Shape</div>
            <div style="display:flex;gap:8px;">
              <button id="shape-circle" class="toggle-btn active" onclick="setMasterShape('circle')" style="flex:1;padding:8px;border:1px solid #dde1e7;border-radius:6px;font-size:13px;font-weight:500;cursor:pointer;background:#0066CC;color:white;border-color:#0066CC;">&#9711; Circle</button>
              <button id="shape-square" class="toggle-btn" onclick="setMasterShape('square')" style="flex:1;padding:8px;border:1px solid #dde1e7;border-radius:6px;font-size:13px;font-weight:500;cursor:pointer;background:white;color:#555;">&#9632; Square</button>
            </div>
          </div>
        </div>
      </div>

      <!-- Social Icons -->
      <div class="master-section">
        <div class="master-section-title">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/></svg>
          Social Icons &mdash; up to 10 (paste icon image URL + profile link)
        </div>
        <div style="display:grid;grid-template-columns:16px 34px 1fr 1fr;gap:8px;margin-bottom:6px;padding:0 0 4px;">
          <span></span><span></span>
          <span style="font-size:11px;font-weight:600;color:#aaa;text-transform:uppercase;letter-spacing:0.4px;">Icon Image URL</span>
          <span style="font-size:11px;font-weight:600;color:#aaa;text-transform:uppercase;letter-spacing:0.4px;">Profile Link URL</span>
        </div>
        <div class="social-rows-list" id="social-rows-list">
          <!-- Rendered by JS -->
        </div>
      </div>

      <!-- Banner -->
      <div class="master-section">
        <div class="master-section-title">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/></svg>
          Banner Image
        </div>
        <div class="banner-section-inner">
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
            <div class="field-group">
              <div class="field-label">Banner Image URL</div>
              <input type="text" id="s-banner-url" placeholder="https://company.com/banner.jpg" oninput="previewBanner(this.value)" />
            </div>
            <div class="field-group">
              <div class="field-label">Banner Click URL</div>
              <input type="text" id="s-banner-link" placeholder="https://company.com" />
            </div>
          </div>
          <div class="banner-preview-wrap" id="banner-preview-wrap">
            <img id="banner-preview" alt="Banner preview" />
          </div>
        </div>
      </div>

    </div>
  </div>

  <!-- EMPLOYEES -->
  <div class="section-header">
    <h2>Employees</h2>
    <button class="btn btn-primary btn-sm admin-only" id="add-emp-table-btn" onclick="openModal()" style="display:none">+ Add Employee</button>
  </div>

  <div style="margin-bottom:16px;">
    <input class="search-box" type="text" id="search" placeholder="Search by name, email, or department&hellip;" oninput="renderTable()" style="max-width:100%;width:100%;" />
  </div>

  <div class="table-wrap">
    <table id="emp-table">
      <thead>
        <tr>
          <th>Employee</th>
          <th>Department</th>
          <th>Email</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody id="table-body"></tbody>
    </table>
    <div class="empty" id="empty-state" style="display:none">
      <h3>No employees yet</h3>
      <p>Click "Add Employee" to create your first signature.</p>
    </div>
  </div>

</div>

<!-- Add Employee Modal -->
<div class="modal-overlay" id="modal">
  <div class="modal">
    <h2>Add Employee</h2>
    <p style="font-size:13px;color:#888;margin:6px 0 20px;">You'll be taken to the full signature editor after adding.</p>
    <form id="emp-form" onsubmit="saveEmployee(event)">
      <div class="form-group">
        <label>Full Name *</label>
        <input type="text" id="f-name" required placeholder="Jane Smith" />
      </div>
      <div class="form-group">
        <label>Work Email *</label>
        <input type="email" id="f-email" required placeholder="jane@company.com" />
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-cancel" onclick="closeModal()">Cancel</button>
        <button type="submit" class="btn btn-primary">Continue to Editor &rarr;</button>
      </div>
    </form>
  </div>
</div>

<div class="toast" id="toast"></div>

<!-- Login Modal -->
<div class="modal-overlay" id="login-modal">
  <div class="modal">
    <h2>&#128274; Admin Login</h2>
    <p style="font-size:13px;color:#888;margin:6px 0 20px;">Enter the admin password to manage signatures.</p>
    <form id="login-form" onsubmit="submitLogin(event)">
      <div class="form-group">
        <label>Password</label>
        <input type="password" id="login-password" required placeholder="Enter admin password" />
      </div>
      <div id="login-error" style="color:#e53e3e;font-size:13px;margin-top:8px;display:none;">Incorrect password. Try again.</div>
      <div class="modal-footer">
        <button type="button" class="btn btn-cancel" onclick="closeLoginModal()">Cancel</button>
        <button type="submit" class="btn btn-primary">Login</button>
      </div>
    </form>
  </div>
</div>

<script>
  let employees = [];
  let isAdmin = false;
  let adminToken = sessionStorage.getItem('adminToken') || '';

  const colors = ['#0066CC','#7B2FBE','#D44D00','#0A8A4A','#C0392B','#2980B9','#8E44AD','#16A085'];

  function adminFetch(url, opts = {}) {
    return fetch(url, { ...opts, headers: { ...(opts.headers || {}), 'x-admin-token': adminToken } });
  }

  async function checkAuth() {
    const res = await fetch('/api/me', { headers: { 'x-admin-token': adminToken } });
    const data = await res.json();
    isAdmin = !!data.admin;
    updateAdminUI();
  }

  function updateAdminUI() {
    document.querySelectorAll('.admin-only').forEach(el => el.style.display = isAdmin ? '' : 'none');
    const btn = document.getElementById('auth-btn');
    btn.textContent = isAdmin ? '&#128275; Logout' : '&#128274; Admin Login';
    btn.innerHTML = isAdmin ? '&#128275; Logout' : '&#128274; Admin Login';
    renderTable();
  }

  function handleAuthBtn() {
    if (isAdmin) logout();
    else openLoginModal();
  }

  function openLoginModal() {
    document.getElementById('login-form').reset();
    document.getElementById('login-error').style.display = 'none';
    document.getElementById('login-modal').classList.add('open');
    setTimeout(() => document.getElementById('login-password').focus(), 50);
  }
  function closeLoginModal() { document.getElementById('login-modal').classList.remove('open'); }

  async function submitLogin(e) {
    e.preventDefault();
    const password = document.getElementById('login-password').value;
    const res = await fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password })
    });
    if (!res.ok) {
      document.getElementById('login-error').style.display = 'block';
      return;
    }
    const { token } = await res.json();
    adminToken = token;
    sessionStorage.setItem('adminToken', token);
    isAdmin = true;
    closeLoginModal();
    updateAdminUI();
    loadSettings();
    showToast('Logged in as admin.');
  }

  async function logout() {
    await adminFetch('/api/logout', { method: 'POST' });
    adminToken = '';
    isAdmin = false;
    sessionStorage.removeItem('adminToken');
    updateAdminUI();
    showToast('Logged out.');
  }

  function getColor(name) {
    let hash = 0;
    for (let c of name) hash = c.charCodeAt(0) + ((hash << 5) - hash);
    return colors[Math.abs(hash) % colors.length];
  }
  function initials(name) {
    return name.split(' ').map(w => w[0]).join('').substring(0,2).toUpperCase();
  }

  // Build 10 social rows in the DOM
  function buildSocialRows() {
    const list = document.getElementById('social-rows-list');
    list.innerHTML = '';
    for (let i = 1; i <= 10; i++) {
      const row = document.createElement('div');
      row.className = 'social-icon-row';
      row.innerHTML = `
        <span class="social-row-num">${i}</span>
        <div class="social-thumb-wrap" id="s-social-thumb-wrap-${i}">
          <img id="s-social-thumb-${i}" alt="" />
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21,15 16,10 5,21"/></svg>
        </div>
        <input type="text" class="icon-url" id="s-social-icon-${i}" placeholder="Paste icon image URL&hellip;" oninput="updateSocialThumb(${i}, this.value)" />
        <input type="text" class="profile-url" id="s-social-link-${i}" placeholder="Paste profile link URL&hellip;" />
      `;
      list.appendChild(row);
    }
  }

  let masterShape = 'circle';
  function setMasterShape(shape) {
    masterShape = shape;
    document.getElementById('shape-circle').style.background = shape === 'circle' ? '#0066CC' : 'white';
    document.getElementById('shape-circle').style.color = shape === 'circle' ? 'white' : '#555';
    document.getElementById('shape-circle').style.borderColor = shape === 'circle' ? '#0066CC' : '#dde1e7';
    document.getElementById('shape-square').style.background = shape === 'square' ? '#0066CC' : 'white';
    document.getElementById('shape-square').style.color = shape === 'square' ? 'white' : '#555';
    document.getElementById('shape-square').style.borderColor = shape === 'square' ? '#0066CC' : '#dde1e7';
  }

  function updateSocialThumb(i, url) {
    const img = document.getElementById('s-social-thumb-' + i);
    const wrap = document.getElementById('s-social-thumb-wrap-' + i);
    if (url && (url.startsWith('http') || url.startsWith('data:'))) {
      img.src = url;
      img.style.display = 'block';
      wrap.querySelector('svg').style.display = 'none';
    } else {
      img.style.display = 'none';
      img.src = '';
      wrap.querySelector('svg').style.display = '';
    }
  }

  function previewLogo(url) {
    const img = document.getElementById('logo-preview');
    if (url && url.startsWith('http')) { img.src = url; img.style.display = 'block'; }
    else { img.style.display = 'none'; }
  }

  function previewBanner(url) {
    const wrap = document.getElementById('banner-preview-wrap');
    const img = document.getElementById('banner-preview');
    if (url && url.startsWith('http')) {
      img.src = url;
      wrap.classList.add('has-banner');
    } else {
      wrap.classList.remove('has-banner');
      img.src = '';
    }
  }

  async function loadSettings() {
    const res = await fetch('/api/settings');
    const s = await res.json();
    document.getElementById('s-company').value      = s.company_name     || '';
    document.getElementById('s-logo').value         = s.company_logo_url || '';
    document.getElementById('s-phone-label').value  = s.company_phone_label  || 'p:';
    document.getElementById('s-phone').value        = s.company_phone    || '';
    document.getElementById('s-address-label').value= s.company_address_label || 'a:';
    document.getElementById('s-address').value      = s.company_address  || '';
    document.getElementById('s-address2').value     = s.company_address2 || '';
    document.getElementById('s-website-label').value= s.company_website_label || 'w:';
    document.getElementById('s-website').value      = s.company_website  || '';
    document.getElementById('s-banner-url').value   = s.banner_url       || '';
    document.getElementById('s-banner-link').value  = s.banner_link      || '';
    setMasterShape(s.photo_shape || 'circle');
    previewLogo(s.company_logo_url || '');
    previewBanner(s.banner_url || '');
    for (let i = 1; i <= 10; i++) {
      const iconUrl = s['social_' + i + '_icon_url'] || '';
      const link    = s['social_' + i + '_link']     || '';
      document.getElementById('s-social-icon-' + i).value = iconUrl;
      document.getElementById('s-social-link-' + i).value = link;
      updateSocialThumb(i, iconUrl);
    }
  }

  async function saveMaster() {
    const btn = document.getElementById('master-save-btn');
    btn.textContent = 'Saving\u2026';
    const data = {
      company_name:          document.getElementById('s-company').value,
      company_logo_url:      document.getElementById('s-logo').value,
      company_phone_label:   document.getElementById('s-phone-label').value || 'p:',
      company_phone:         document.getElementById('s-phone').value,
      company_address_label: document.getElementById('s-address-label').value || 'a:',
      company_address:       document.getElementById('s-address').value,
      company_address2:      document.getElementById('s-address2').value,
      company_website_label: document.getElementById('s-website-label').value || 'w:',
      company_website:       document.getElementById('s-website').value,
      banner_url:            document.getElementById('s-banner-url').value,
      banner_link:           document.getElementById('s-banner-link').value,
      photo_shape:           masterShape,
    };
    for (let i = 1; i <= 10; i++) {
      data['social_' + i + '_icon_url'] = document.getElementById('s-social-icon-' + i).value;
      data['social_' + i + '_link']     = document.getElementById('s-social-link-' + i).value;
    }
    await adminFetch('/api/settings', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(data) });
    btn.textContent = '\u2713 Saved!';
    btn.classList.add('saved');
    setTimeout(() => { btn.textContent = 'Save Master Template'; btn.classList.remove('saved'); }, 2500);
    showToast('Master template saved. All signatures updated.');
  }

  async function loadEmployees() {
    const res = await fetch('/api/employees');
    employees = await res.json();
    renderTable();
  }

  function renderTable() {
    const q = document.getElementById('search').value.toLowerCase();
    const filtered = employees.filter(e =>
      e.name.toLowerCase().includes(q) ||
      (e.email || '').toLowerCase().includes(q) ||
      (e.department || '').toLowerCase().includes(q)
    );
    document.getElementById('header-count').textContent = `${employees.length} employee${employees.length !== 1 ? 's' : ''}`;
    const tbody = document.getElementById('table-body');
    if (filtered.length === 0) {
      tbody.innerHTML = '';
      document.getElementById('empty-state').style.display = 'block';
      document.getElementById('emp-table').style.display = employees.length === 0 ? 'none' : 'table';
      return;
    }
    document.getElementById('empty-state').style.display = 'none';
    document.getElementById('emp-table').style.display = 'table';
    tbody.innerHTML = filtered.map(e => `
      <tr>
        <td><div class="name-cell"><div class="avatar" style="background:${getColor(e.name)}">${initials(e.name)}</div><div><div class="name-text">${e.name}</div><div class="sub-text">${e.title || '\u2014'}</div></div></div></td>
        <td>${e.department ? `<span class="badge">${e.department}</span>` : '\u2014'}</td>
        <td style="color:#0066CC">${e.email}</td>
        <td><div class="actions">
          <button class="copy-link" id="copy-${e.id}" onclick="copyLink('${e.id}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg> Copy Link</button>
          ${isAdmin ? `<a href="/edit/${e.id}" class="btn btn-sm" style="background:#f0f2f5;color:#333;text-decoration:none;">Edit</a>` : ''}
          ${isAdmin ? `<button class="btn btn-sm btn-danger" onclick="deleteEmployee('${e.id}', '${e.name.replace(/'/g,"\\'")}')">Delete</button>` : ''}
        </div></td>
      </tr>
    `).join('');
  }

  function copyLink(id) {
    const url = `${location.origin}/signature/${id}`;
    navigator.clipboard.writeText(url).then(() => {
      const btn = document.getElementById(`copy-${id}`);
      btn.textContent = '\u2713 Copied!';
      btn.classList.add('copied');
      setTimeout(() => { btn.innerHTML = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg> Copy Link`; btn.classList.remove('copied'); }, 2000);
    });
  }

  function openModal() { document.getElementById('emp-form').reset(); document.getElementById('modal').classList.add('open'); document.getElementById('f-name').focus(); }
  function closeModal() { document.getElementById('modal').classList.remove('open'); }

  async function saveEmployee(e) {
    e.preventDefault();
    const name  = document.getElementById('f-name').value;
    const email = document.getElementById('f-email').value;
    const res = await adminFetch('/api/employees', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, email }) });
    const { id } = await res.json();
    location.href = `/edit/${id}`;
  }

  async function deleteEmployee(id, name) {
    if (!confirm(`Delete signature for ${name}?`)) return;
    await adminFetch(`/api/employees/${id}`, { method: 'DELETE' });
    await loadEmployees();
    showToast('Employee deleted.');
  }

  function showToast(msg) {
    const t = document.getElementById('toast');
    t.textContent = msg; t.classList.add('show');
    setTimeout(() => t.classList.remove('show'), 2500);
  }

  document.getElementById('modal').addEventListener('click', function(e) { if (e.target === this) closeModal(); });
  document.getElementById('login-modal').addEventListener('click', function(e) { if (e.target === this) closeLoginModal(); });

  buildSocialRows();
  checkAuth().then(() => { if (isAdmin) loadSettings(); });
  loadEmployees();
</script>
</body>
</html>

